document.addEventListener("DOMContentLoaded",function(){const t=document.getElementById("withdraw-form");t&&t.addEventListener("submit",function(e){e.preventDefault(),(e=new FormData(this)).append("action","requestWithdrawal"),fetch("../controllers/WithdrawController.php",{method:"POST",body:e}).then(e=>e.json()).then(e=>{e.success?(Toastify({text:e.message,duration:3e3,className:"info",style:{background:"linear-gradient(to right, #00b09b, #96c93d)"}}).showToast(),t.reset(),setTimeout(()=>{location.reload()},2e3)):Toastify({text:e.message||"An unknown error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}).catch(e=>{console.error("Error:",e),Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})})});
